 1	/**
 2	 * Shared DOM utilities — Repo Parallelizer GUI.
 3	 *
 4	 * @module utils/dom
 5	 */
 6	
 7	/**
 8	 * Remove all child nodes from a DOM element without using `innerHTML`.
 9	 *
10	 * Preferred over `el.innerHTML = ''` because it avoids invoking the HTML
11	 * parser and is safe even when the element's children hold event listeners
12	 * that should be GC'd cleanly.
13	 *
14	 * @param {Element} el - The element to empty.
15	 */
16	export function clearElement(el) {
17	    while (el.firstChild) el.removeChild(el.firstChild);
18	}
19	
20	/**
21	 * Build a CSS-styled credential badge `<span>` for a repository.
22	 *
23	 * Replaces the previous emoji-based approach (`🔑` / `—`) with a CSS-styled
24	 * element that renders consistently across platforms and is accessible via
25	 * `aria-label`.
26	 *
27	 * The returned element always carries the base `.credential-badge` class plus
28	 * one of:
29	 *   - `.credential-badge--set`  — a credential is configured.
30	 *   - `.credential-badge--none` — no credential is configured.
31	 *
32	 * @param {string|null|undefined} credentialId - The credential ID, or null/undefined when absent.
33	 * @returns {HTMLSpanElement}
34	 *
35	 * @example
36	 * // Credential set
37	 * const badge = buildCredentialBadge('my-cred-id');
38	 * // badge.classList → ['credential-badge', 'credential-badge--set']
39	 *
40	 * @example
41	 * // No credential
42	 * const badge = buildCredentialBadge(null);
43	 * // badge.classList → ['credential-badge', 'credential-badge--none']
44	 */
45	export function buildCredentialBadge(credentialId) {
46	    const span = document.createElement('span');
47	    if (credentialId) {
48	        span.className   = 'credential-badge credential-badge--set';
49	        span.title       = `Credential: ${credentialId}`;
50	        span.textContent = '✓';
51	        span.setAttribute('aria-label', 'Credential configured');
52	    } else {
53	        span.className   = 'credential-badge credential-badge--none';
54	        span.title       = 'No credential configured';
55	        span.textContent = '—';
56	        span.setAttribute('aria-label', 'No credential configured');
57	    }
58	    return span;
59	}

  1	/**
  2	 * Repositories View — Repo Parallelizer GUI.
  3	 *
  4	 * Renders a full CRUD management page for all registered repositories:
  5	 *   - Table listing all repositories (ID, Name, URL).
  6	 *   - "Add Repository" inline form (URL required, Name optional, ID optional).
  7	 *   - Inline edit for repository Name per row.
  8	 *   - Delete per row with a confirmation dialog.
  9	 *
 10	 * @param {HTMLElement} container - The `#app` root element supplied by the router.
 11	 * @param {Object}      _params   - Route params (none for this route).
 12	 */
 13	
 14	import { api } from '../api.js';
 15	import { showToast } from '../components/toast.js';
 16	import { showConfirm } from '../components/confirm-dialog.js';
 17	import { createFormField, validateRequired } from '../components/form-helpers.js';
 18	import { normaliseRepo } from '../utils/normalise.js';
 19	import { clearElement, buildCredentialBadge } from '../utils/dom.js';
 20	import { APP_NAME_SHORT } from '../utils/constants.js';
 21	
 22	// ---------------------------------------------------------------------------
 23	// Table rendering
 24	// ---------------------------------------------------------------------------
 25	
 26	/**
 27	 * Build the `<thead>` element for the repository table.
 28	 *
 29	 * @returns {HTMLElement}
 30	 */
 31	function buildTableHead() {
 32	    const thead = document.createElement('thead');
 33	    const tr    = document.createElement('tr');
 34	
 35	    ['ID', 'Name', 'URL', 'Credential', 'Actions'].forEach((label) => {
 36	        const th = document.createElement('th');
 37	        th.textContent = label;
 38	        tr.appendChild(th);
 39	    });
 40	
 41	    thead.appendChild(tr);
 42	    return thead;
 43	}
 44	
 45	/**
 46	 * Build a single `<tr>` for one repository.
 47	 *
 48	 * The row starts in read mode.  The Name cell renders as a clickable `<a>`
 49	 * link navigating to `#/repositories/:id`.  Clicking Edit switches the Name
 50	 * cell to an inline `<input>` and replaces the action buttons with Save / Cancel.
 51	 * Clicking Delete shows a confirmation dialog and calls the API on confirm.
 52	 *
 53	 * @param {{ id: string, name: string, url: string }} repo
 54	 * @param {function(): void} onDeleted - Callback to refresh the table after deletion.
 55	 * @returns {HTMLTableRowElement}
 56	 */
 57	function buildRepoRow(repo, onDeleted) {
 58	    const tr = document.createElement('tr');
 59	    tr.dataset.repoId = repo.id;
 60	
 61	    // ---- ID cell (read-only) ----
 62	    const idCell = document.createElement('td');
 63	    idCell.className = 'repo-id-cell text-muted';
 64	    idCell.textContent = repo.id;
 65	    tr.appendChild(idCell);
 66	
 67	    // ---- Name cell (editable) ----
 68	    const nameCell = document.createElement('td');
 69	    nameCell.className = 'repo-name-cell';
 70	
 71	    const nameLink = document.createElement('a');
 72	    nameLink.className = 'repo-name-display repo-name-link';
 73	    nameLink.href      = `#/repositories/${encodeURIComponent(repo.id)}`;
 74	    nameLink.textContent = repo.name || '—';
 75	    nameCell.appendChild(nameLink);
 76	
 77	    // Inline edit input (hidden initially)
 78	    const nameInput = document.createElement('input');
 79	    nameInput.type       = 'text';
 80	    nameInput.className  = 'form-input repo-name-input';
 81	    nameInput.value      = repo.name;
 82	    nameInput.hidden     = true;
 83	    nameInput.setAttribute('aria-label', `Name for repository ${repo.id}`);
 84	    nameCell.appendChild(nameInput);
 85	
 86	    tr.appendChild(nameCell);
 87	
 88	    // ---- URL cell (read-only) ----
 89	    const urlCell = document.createElement('td');
 90	    urlCell.className = 'repo-url-cell';
 91	    const urlLink = document.createElement('a');
 92	    urlLink.href      = repo.url;
 93	    urlLink.textContent = repo.url;
 94	    urlLink.target    = '_blank';
 95	    urlLink.rel       = 'noopener noreferrer';
 96	    urlLink.className = 'repo-url-link';
 97	    urlCell.appendChild(urlLink);
 98	    tr.appendChild(urlCell);
 99	
100	    // ---- Credential status cell ----

101	    const credentialCell = document.createElement('td');
102	    credentialCell.className = 'repo-credential-cell';
103	    credentialCell.appendChild(buildCredentialBadge(repo.credentialId));
104	    tr.appendChild(credentialCell);
105	
106	    // ---- Actions cell ----
107	    const actionsCell = document.createElement('td');
108	    actionsCell.className = 'repo-actions-cell';
109	
110	    // Read-mode buttons
111	    const editBtn = document.createElement('button');
112	    editBtn.type      = 'button';
113	    editBtn.className = 'btn btn-secondary btn-sm';
114	    editBtn.textContent = 'Edit';
115	
116	    const deleteBtn = document.createElement('button');
117	    deleteBtn.type      = 'button';
118	    deleteBtn.className = 'btn btn-danger btn-sm';
119	    deleteBtn.textContent = 'Delete';
120	
121	    // Edit-mode buttons (hidden initially)
122	    const saveBtn = document.createElement('button');
123	    saveBtn.type      = 'button';
124	    saveBtn.className = 'btn btn-primary btn-sm';
125	    saveBtn.textContent = 'Save';
126	    saveBtn.hidden    = true;
127	
128	    const cancelEditBtn = document.createElement('button');
129	    cancelEditBtn.type      = 'button';
